using System.Collections.Generic;using Alterverse.AI;using Alterverse.Characters;using Alterverse.Combat;using UnityEngine;
namespace Alterverse.Match
{
public sealed class MatchScoreboard:MonoBehaviour
{
private sealed class Entry{public TeamMember Member;public string Name;public int Kills,Deaths,Assists;public int Score=>Kills*100+Assists*50;}public static MatchScoreboard Instance{get;private set;}[SerializeField]private float refreshInterval=.5f,assistWindow=8f;private readonly Dictionary<Health,Entry> entries=new();private readonly Dictionary<Health,Dictionary<TeamMember,float>> damageCredit=new();private float nextRefresh;private HeroRespawn playerRespawn;private DimensionsFront front;private GUIStyle header,row,respawnStyle,frontStyle;
private void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;}private void Start(){RefreshRoster();playerRespawn=Object.FindAnyObjectByType<HeroRespawn>();front=Object.FindAnyObjectByType<DimensionsFront>();}private void Update(){if(Time.unscaledTime>=nextRefresh){nextRefresh=Time.unscaledTime+refreshInterval;RefreshRoster();playerRespawn??=Object.FindAnyObjectByType<HeroRespawn>();front??=Object.FindAnyObjectByType<DimensionsFront>();}}
private static bool IsHero(TeamMember member)=>member!=null&&(member.GetComponent<HeroRespawn>()!=null||member.GetComponent<MobaBotRespawn>()!=null);public void RecordDamage(Health victim,GameObject source){if(victim==null||source==null)return;TeamMember attacker=source.GetComponentInParent<TeamMember>(),victimTeam=victim.GetComponent<TeamMember>();if(!IsHero(attacker)||!IsHero(victimTeam)||attacker.Team==victimTeam.Team)return;if(!damageCredit.TryGetValue(victim,out Dictionary<TeamMember,float> credits)){credits=new();damageCredit[victim]=credits;}credits[attacker]=Time.time;}
private void RefreshRoster(){foreach(TeamMember member in Object.FindObjectsByType<TeamMember>(FindObjectsSortMode.None)){if(!IsHero(member))continue;Health health=member.GetComponent<Health>();if(health==null||entries.ContainsKey(health))continue;HeroIdentity identity=member.GetComponent<HeroIdentity>();entries.Add(health,new Entry{Member=member,Name=identity!=null?identity.DisplayName:DisplayName(member.gameObject.name)});health.DiedWithSource+=OnHeroDied;}}private void OnHeroDied(Health victim,GameObject source){if(victim==null||!entries.TryGetValue(victim,out Entry victimEntry))return;victimEntry.Deaths++;TeamMember killer=source!=null?source.GetComponentInParent<TeamMember>():null;if(IsHero(killer)&&killer.Team!=victimEntry.Member.Team){Entry killerEntry=FindEntry(killer);if(killerEntry!=null)killerEntry.Kills++;if(damageCredit.TryGetValue(victim,out Dictionary<TeamMember,float> credits))foreach(var credit in credits)if(IsHero(credit.Key)&&credit.Key!=killer&&Time.time-credit.Value<=assistWindow&&credit.Key.Team==killer.Team){Entry assist=FindEntry(credit.Key);if(assist!=null)assist.Assists++;}}damageCredit.Remove(victim);}private Entry FindEntry(TeamMember member){foreach(Entry e in entries.Values)if(e.Member==member)return e;return null;}private static string DisplayName(string raw)=>raw=="AV_Player"?"HERO":raw.Replace("AV_","").Replace("Bot_"," ");private int TeamKills(int team){int total=0;foreach(Entry e in entries.Values)if(e.Member.Team==team)total+=e.Kills;return total;}
private void OnGUI(){header??=new GUIStyle(GUI.skin.label){fontSize=17,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};row??=new GUIStyle(GUI.skin.label){fontSize=15,alignment=TextAnchor.MiddleCenter};respawnStyle??=new GUIStyle(GUI.skin.button){fontSize=22,fontStyle=FontStyle.Bold};frontStyle??=new GUIStyle(GUI.skin.label){fontSize=14,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};float compactWidth=Mathf.Min(330,Screen.width*.44f),compactX=(Screen.width-compactWidth)*.5f;GUI.Box(new Rect(compactX,42,compactWidth,48),GUIContent.none);GUI.Label(new Rect(compactX,43,compactWidth,23),$"ZERO  {TeamKills(0)}   •   {TeamKills(1)}  LUMEN",header);if(front!=null)GUI.Label(new Rect(compactX,65,compactWidth,20),$"FRONT  {front.ZeroControl:0}%  ◀  ▶  {front.LumenControl:0}%",frontStyle);if(playerRespawn==null||!playerRespawn.IsRespawning)return;float width=Mathf.Min(680,Screen.width*.82f),x=(Screen.width-width)*.5f,y=Mathf.Max(90,Screen.height*.15f);List<Entry> zero=new(),lumen=new();foreach(Entry e in entries.Values)(e.Member.Team==0?zero:lumen).Add(e);zero.Sort((a,b)=>b.Score.CompareTo(a.Score));lumen.Sort((a,b)=>b.Score.CompareTo(a.Score));float boardHeight=82+Mathf.Max(zero.Count,lumen.Count)*27;GUI.Box(new Rect(x,y,width,boardHeight+82),GUIContent.none);GUI.Label(new Rect(x,y+5,width,25),"DIMENSIONS FRONT  •  K / D / A / SCORE",header);if(front!=null)GUI.Label(new Rect(x,y+30,width,22),$"REALITY FRONT   ZERO {front.ZeroControl:0.0}%   |   LUMEN {front.LumenControl:0.0}%",frontStyle);DrawTeam(zero,x+10,y+57,width*.5f-15,"ZERO");DrawTeam(lumen,x+width*.5f+5,y+57,width*.5f-15,"LUMEN");Rect action=new(x+width*.25f,y+boardHeight+18,width*.5f,48);if(playerRespawn.RespawnReady){if(GUI.Button(action,"RESPAWN",respawnStyle))playerRespawn.ConfirmRespawn();}else GUI.Label(action,$"RESPAWN IN  {Mathf.CeilToInt(playerRespawn.RemainingSeconds)}",header);}
private void DrawTeam(List<Entry> team,float x,float y,float width,string title){GUI.Label(new Rect(x,y,width,22),title,header);for(int i=0;i<team.Count;i++){Entry e=team[i];GUI.Label(new Rect(x,y+24+i*27,width,24),$"{e.Name,-13}   {e.Kills} / {e.Deaths} / {e.Assists} / {e.Score}",row);}}private void OnDestroy(){foreach(var pair in entries)if(pair.Key!=null)pair.Key.DiedWithSource-=OnHeroDied;entries.Clear();if(Instance==this)Instance=null;}
}
}
